@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class NicrosilFeruchemyGameTests {
    private static FakePlayer player(GameTestHelper h,boolean ferring){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"Nicrosil"));p.setGameMode(GameType.SURVIVAL);p.setPos(net.minecraft.world.phys.Vec3.atCenterOf(h.absolutePos(new BlockPos(1,5,1))));if(ferring)PowerAttributes.set(p,"f:nicrosil",1);return p;}
    private static ItemStack ring(String metal){return new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.fromNamespaceAndPath(CosmereArcanists.MOD_ID,metal+"_metalmind_ring")));}
    private static ItemStack equip(FakePlayer p){var ring=ring("nicrosil");p.setItemInHand(InteractionHand.OFF_HAND,ring);PowerData.state(p,"f:nicrosil",-1);return ring;}
    private static void unkey(FakePlayer p){PowerAttributes.set(p,"f:aluminum",1);p.setItemInHand(InteractionHand.MAIN_HAND,ring("aluminum"));PowerData.state(p,"f:aluminum",-10);AluminumFeruchemy.tick(p);if(!AluminumFeruchemy.unkeyedStorage(p))throw new AssertionError("Fully funded Identity suppression expected");}
    private static NicrosilService.Session open(FakePlayer p,ItemStack stack){var s=NicrosilService.open(p,stack);if(s==null)throw new AssertionError("Expected nicrosil menu");return s;}
    private static long storageClock=10000;
    private static String store(NicrosilService.Session s,int kind,String key){double rate=NicrosilConfig.POWER_RATE.get();try{NicrosilConfig.POWER_RATE.set(1024.0);String result=NicrosilService.store(s,kind,key);NicrosilService.storageTick(s.player,++storageClock);return result;}finally{NicrosilConfig.POWER_RATE.set(rate);}}
    private static void clean(FakePlayer p,ItemStack stack){NicrosilService.clear(p);Metalminds.wipe(stack);AluminumFeruchemy.clear(p);}
    @GameTest(template="empty") public static void storingRemovesExactPowerAndOwnerCanReclaimItPermanently(GameTestHelper h){
        var p=player(h,true);var ring=equip(p);try{PowerAttributes.set(p,"a:steel",1.5);PowerData.reserve(p,"steel",40);PowerData.state(p,"a:steel",2);var s=open(p,ring);store(s,0,"a:steel");var mind=NicrosilService.contents(p,ring);h.assertTrue(mind!=null&&mind.entries().size()==1&&PowerAttributes.baseStrength(p,"a:steel")==0&&PowerData.state(p,"a:steel")==0,"A whole power moves to the metalmind and stops burning");var entry=mind.entries().getFirst();h.assertTrue(entry.amount()==1.5&&Metalminds.charge(ring)==150&&PowerData.reserve(p,"steel")==40,"Strength and capacity are exact; a power transfer does not transfer metal reserves");s.storing=false;NicrosilService.tap(s,entry.id());h.assertTrue(PowerAttributes.baseStrength(p,"a:steel")==1.5&&!Metalminds.bound(ring),"Owner reclaims a permanent power and empties the item");PowerAttributes.migrate(p);var clone=player(h,false);PowerData.clonePlayer(p,clone);h.assertTrue(PowerAttributes.baseStrength(clone,"a:steel")==1.5,"Granted powers survive player cloning");h.assertTrue(PowerRules.implemented("f:nicrosil")&&PowerData.storeLevels(p,"f:nicrosil")==1&&PowerData.tapLevels(p,"f:nicrosil")==1,"Discrete modes are integrated into the selector");}finally{clean(p,ring);}h.succeed();
    }
    @GameTest(template="empty") public static void anyoneCanTapUnkeyedNicrosilAndCopiedItemsCannotClaimTwice(GameTestHelper h){
        var donor=player(h,true);var ring=equip(donor);var receiver=player(h,false);try{unkey(donor);PowerAttributes.set(donor,"f:gold",1.75);var s=open(donor,ring);store(s,0,"f:gold");h.assertTrue(Metalminds.unkeyed(ring),"Paid full Identity suppression creates unkeyed stored powers");var entry=NicrosilService.contents(donor,ring).entries().getFirst();var copied=ring.copy();donor.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);receiver.setItemInHand(InteractionHand.OFF_HAND,ring);var use=new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickItem(receiver,InteractionHand.OFF_HAND);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(use);var tap=NicrosilService.session(receiver);h.assertTrue(use.isCanceled()&&tap!=null,"Native right-click opens the menu for a powerless recipient");h.assertTrue(PowerAttributes.strength(receiver,"f:nicrosil")==0,"An ordinary recipient can open the unkeyed tapping menu");NicrosilService.tap(tap,entry.id());h.assertTrue(PowerAttributes.baseStrength(receiver,"f:gold")==1.75,"The recipient gains the stored power permanently");PowerAttributes.set(receiver,"f:gold",0);receiver.setItemInHand(InteractionHand.OFF_HAND,copied);h.assertTrue(NicrosilService.open(receiver,copied)==null&&PowerAttributes.baseStrength(receiver,"f:gold")==0,"A stale copy is emptied and cannot restore a consumed power");}finally{clean(donor,ring);NicrosilService.clear(receiver);}h.succeed();
    }
    @GameTest(template="empty") public static void keyedIdentityAndUnkeyedStorageRequirementsRemainAuthoritative(GameTestHelper h){
        var donor=player(h,true);var ring=equip(donor);var other=player(h,true);try{PowerAttributes.set(donor,"a:iron",1);store(open(donor,ring),0,"a:iron");donor.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);other.setItemInHand(InteractionHand.OFF_HAND,ring);h.assertTrue(NicrosilService.open(other,ring)==null,"Matching Feruchemy cannot bypass another donor's Identity");other.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);donor.setItemInHand(InteractionHand.OFF_HAND,ring);unkey(donor);var s=open(donor,ring);PowerAttributes.set(donor,"a:tin",1);store(s,0,"a:tin");h.assertTrue(PowerAttributes.baseStrength(donor,"a:tin")==1&&NicrosilService.contents(donor,ring).entries().size()==1,"Identity suppression cannot rewrite a previously keyed nicrosilmind");}finally{clean(donor,ring);NicrosilService.clear(other);}h.succeed();
    }
    @GameTest(template="empty") public static void nicrosilSelfStorageRequiresUnkeyedAccessAndCanBeReclaimedWithoutThePower(GameTestHelper h){
        var p=player(h,true);var ring=equip(p);try{var s=open(p,ring);store(s,0,"f:nicrosil");h.assertTrue(PowerAttributes.baseStrength(p,"f:nicrosil")==1&&NicrosilService.contents(p,ring)==null,"Self-storage cannot trap nicrosil in an inaccessible keyed item");unkey(p);store(s,0,"f:nicrosil");var entry=NicrosilService.contents(p,ring).entries().getFirst();h.assertTrue(PowerAttributes.baseStrength(p,"f:nicrosil")==0&&Metalminds.unkeyed(ring),"The donor really loses Feruchemical nicrosil");var reclaim=open(p,ring);NicrosilService.tap(reclaim,entry.id());h.assertTrue(PowerAttributes.baseStrength(p,"f:nicrosil")==1,"Universal unkeyed tapping allows reclaiming nicrosil itself");}finally{clean(p,ring);}h.succeed();
    }
    @GameTest(template="empty") public static void externalAndFutureSpikeContributionsNeverBecomeTransferablePowers(GameTestHelper h){
        var p=player(h,true);var ring=equip(p);var modifier=ResourceLocation.fromNamespaceAndPath(CosmereArcanists.MOD_ID,"test_spike_strength");var attribute=BuiltInRegistries.ATTRIBUTE.getHolder(ResourceLocation.fromNamespaceAndPath(CosmereArcanists.MOD_ID,"allomancy_steel")).orElseThrow();try{PowerAttributes.set(p,"a:steel",1.5);p.getAttribute(attribute).addTransientModifier(new AttributeModifier(modifier,1,AttributeModifier.Operation.ADD_VALUE));h.assertTrue(PowerAttributes.strength(p,"a:steel")==2.5,"Fixture combines personal and externally supplied strength");var s=open(p,ring);store(s,0,"a:steel");h.assertTrue(PowerAttributes.strength(p,"a:steel")==1&&NicrosilService.contents(p,ring).entries().getFirst().amount()==1.5,"Only personal base strength is removed/stored, leaving the spike-style modifier intact");store(s,0,"a:steel");h.assertTrue(NicrosilService.contents(p,ring).entries().size()==1,"An exclusively external power cannot be deposited");}finally{p.getAttribute(attribute).removeModifier(modifier);clean(p,ring);}h.succeed();
    }
    @GameTest(template="empty") public static void capacityContactAndFeatureFailuresPreserveTheDonorsPower(GameTestHelper h){
        var p=player(h,true);var ring=equip(p);double charge=NicrosilConfig.POWER_CHARGE.get();boolean enabled=NicrosilConfig.ENABLED.get();try{PowerAttributes.set(p,"a:steel",1.5);var s=open(p,ring);NicrosilConfig.POWER_CHARGE.set(1000000.0);store(s,0,"a:steel");h.assertTrue(PowerAttributes.baseStrength(p,"a:steel")>1.49&&Math.abs(PowerAttributes.baseStrength(p,"a:steel")+NicrosilService.contents(p,ring).entries().getFirst().amount()-1.5)<1e-9,"Limited capacity stores only the fraction that fits and conserves total strength");NicrosilService.stopStorage(p,"Test reset");Metalminds.wipe(ring);PowerAttributes.set(p,"a:steel",1.5);NicrosilConfig.POWER_CHARGE.set(charge);p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);store(s,0,"a:steel");h.assertTrue(PowerAttributes.baseStrength(p,"a:steel")==1.5,"Losing contact invalidates a pending menu action");p.setItemInHand(InteractionHand.OFF_HAND,ring);ring.setCount(2);store(s,0,"a:steel");h.assertTrue(PowerAttributes.baseStrength(p,"a:steel")==1.5,"Stacked pieces cannot store powers");ring.setCount(1);NicrosilConfig.ENABLED.set(false);store(s,0,"a:steel");h.assertTrue(PowerAttributes.baseStrength(p,"a:steel")==1.5,"Disabling the feature blocks an already open menu");}finally{NicrosilConfig.POWER_CHARGE.set(charge);NicrosilConfig.ENABLED.set(enabled);clean(p,ring);}h.succeed();
    }
    @GameTest(template="empty") public static void overlapSaveReloadAndWipingNeverDuplicateOrDiscardUnclaimedPowers(GameTestHelper h){
        var p=player(h,true);var ring=equip(p);try{PowerAttributes.set(p,"a:steel",1.5);var s=open(p,ring);store(s,0,"a:steel");var mind=NicrosilService.contents(p,ring);var entry=mind.entries().getFirst();var saved=NicrosilData.get(p.server).save(new CompoundTag(),h.getLevel().registryAccess());var loaded=NicrosilData.load(saved,h.getLevel().registryAccess());h.assertTrue(loaded.ledger.get(mind.id).entry(entry.id()).amount()==1.5&&loaded.ledger.get(mind.id).owner.equals(p.getUUID()),"Saved contents preserve identity, strength and unique entry IDs");PowerAttributes.set(p,"a:steel",1023);s.storing=false;NicrosilService.tap(s,entry.id());h.assertTrue(PowerAttributes.baseStrength(p,"a:steel")==1023&&mind.entry(entry.id())!=null,"The total strength ceiling blocks overflow without losing the stored entry");h.assertTrue(Metalminds.transfer(ring,p.getUUID(),"nicrosil",-150)==0,"Ordinary charge drains cannot silently consume permanent powers");var copied=ring.copy();h.assertTrue(Metalminds.wipe(ring)&&NicrosilData.get(p.server).ledger.get(mind.id)==null,"Wiping removes the authoritative shared inventory");p.setItemInHand(InteractionHand.OFF_HAND,copied);var reopened=open(p,copied);h.assertTrue(NicrosilService.contents(p,copied)==null&&!Metalminds.bound(copied),"Opening a stale wiped copy cannot restore erased contents");NicrosilService.tap(reopened,entry.id());h.assertTrue(PowerAttributes.baseStrength(p,"a:steel")==1023,"The erased power cannot be claimed");}finally{clean(p,ring);}h.succeed();
    }
    @GameTest(template="empty") public static void nicrosilPacketsRoundTripAndRejectMalformedChoices(GameTestHelper h){
        var row=new NicrosilNetwork.Row(UUID.randomUUID(),0,"a:steel","Allomantic Steel",1.5,true);var packet=new NicrosilNetwork.Snapshot(true,UUID.randomUUID(),"Unkeyed nicrosilmind",false,false,true,150,600,List.of(row),"Ready",true,"Steel: 0.25 / 0.5");var buf=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{NicrosilNetwork.Snapshot.CODEC.encode(buf,packet);h.assertTrue(NicrosilNetwork.Snapshot.CODEC.decode(buf).equals(packet),"Bounded nicrosil snapshots preserve entry IDs, permissions and strength");buf.clear();var request=new NicrosilNetwork.Request(NicrosilNetwork.TAP,packet.session(),row.entry(),0,row.key(),.5);NicrosilNetwork.Request.CODEC.encode(buf,request);h.assertTrue(NicrosilNetwork.Request.CODEC.decode(buf).equals(request),"Requests carry a bounded storage target while the server controls actual progress");}finally{buf.release();}
        boolean rejected=false;try{new NicrosilNetwork.Row(UUID.randomUUID(),0,"a:steel","Invalid",Double.NaN,true);}catch(IllegalArgumentException expected){rejected=true;}h.assertTrue(rejected,"Nonfinite amounts are rejected");rejected=false;try{new NicrosilNetwork.Snapshot(true,UUID.randomUUID(),"Too many",false,false,true,150,600,Collections.nCopies(257,row),"");}catch(IllegalArgumentException expected){rejected=true;}h.assertTrue(rejected,"Snapshot rows have a hard bound");rejected=false;try{new NicrosilNetwork.Request(99,UUID.randomUUID(),UUID.randomUUID(),0,"");}catch(IllegalArgumentException expected){rejected=true;}h.assertTrue(rejected,"Unknown menu actions are rejected");h.succeed();
    }
    @GameTest(template="empty") public static void gradualStorageCanSplitAnExactPortionAndRecombineItWithoutLoss(GameTestHelper h){
        var p=player(h,true);var ring=equip(p);double rate=NicrosilConfig.POWER_RATE.get();try{NicrosilConfig.POWER_RATE.set(1.0);PowerAttributes.set(p,"a:steel",1);var s=open(p,ring);NicrosilService.store(s,0,"a:steel",.5);h.assertTrue(PowerAttributes.baseStrength(p,"a:steel")==1&&NicrosilService.contents(p,ring)==null,"Starting storage transfers nothing immediately");NicrosilService.storageTick(p,++storageClock);double first=PowerAttributes.baseStrength(p,"a:steel");h.assertTrue(first>.94&&first<1,"The first tick moves a fraction and leaves the donor's power usable");var entryId=NicrosilService.contents(p,ring).entries().getFirst().id();NicrosilService.storageTick(p,storageClock);h.assertTrue(PowerAttributes.baseStrength(p,"a:steel")==first,"A repeated tick call cannot accelerate storage");for(int i=0;i<20&&NicrosilService.storing(p);i++)NicrosilService.storageTick(p,++storageClock);var mind=NicrosilService.contents(p,ring);var entry=mind.entries().getFirst();h.assertTrue(Math.abs(PowerAttributes.baseStrength(p,"a:steel")-.5)<1e-9&&Math.abs(entry.amount()-.5)<1e-9&&!NicrosilService.storing(p),"A target of0.5 leaves half the personal power and stores half");h.assertTrue(mind.entries().size()==1&&entry.id().equals(entryId)&&Math.abs(entry.charge()-50)<1e-8,"Many incremental ticks share one stable entry and proportional capacity");s.storing=false;NicrosilService.tap(s,entry.id());h.assertTrue(Math.abs(PowerAttributes.baseStrength(p,"a:steel")-1)<1e-9&&!Metalminds.bound(ring),"Tapping adds the stored portion back to the remaining personal strength");}finally{NicrosilConfig.POWER_RATE.set(rate);clean(p,ring);}h.succeed();
    }
    @GameTest(template="empty") public static void partialUnkeyedPowersGiveAnotherPlayerOnlyTheStoredFraction(GameTestHelper h){
        var donor=player(h,true);var ring=equip(donor);var receiver=player(h,false);double rate=NicrosilConfig.POWER_RATE.get();try{NicrosilConfig.POWER_RATE.set(1.0);unkey(donor);PowerAttributes.set(donor,"a:steel",1);var s=open(donor,ring);NicrosilService.store(s,0,"a:steel",.5);for(int i=0;i<20&&NicrosilService.storing(donor);i++)NicrosilService.storageTick(donor,++storageClock);var entry=NicrosilService.contents(donor,ring).entries().getFirst();donor.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);receiver.setItemInHand(InteractionHand.OFF_HAND,ring);NicrosilService.tap(open(receiver,ring),entry.id());h.assertTrue(Math.abs(PowerAttributes.baseStrength(donor,"a:steel")-.5)<1e-9&&Math.abs(PowerAttributes.baseStrength(receiver,"a:steel")-.5)<1e-9,"A normal power splits into two permanently weaker powers without duplication");}finally{NicrosilConfig.POWER_RATE.set(rate);clean(donor,ring);NicrosilService.clear(receiver);}h.succeed();
    }
    @GameTest(template="empty") public static void menuClosingContinuesStorageButOffAndContactLossStopIt(GameTestHelper h){
        var p=player(h,true);var ring=equip(p);double rate=NicrosilConfig.POWER_RATE.get();try{NicrosilConfig.POWER_RATE.set(1.0);PowerAttributes.set(p,"a:steel",1);var s=open(p,ring);NicrosilService.store(s,0,"a:steel",.5);NicrosilService.request(p,new NicrosilNetwork.Request(NicrosilNetwork.CLOSE,s.token,NicrosilNetwork.ZERO,0,""));h.assertTrue(NicrosilService.session(p)==null&&NicrosilService.storing(p),"Closing the menu leaves the deliberate storage choice active");NicrosilService.storageTick(p,++storageClock);double partial=PowerAttributes.baseStrength(p,"a:steel");PowerData.state(p,"f:nicrosil",0);NicrosilService.storageTick(p,++storageClock);h.assertTrue(!NicrosilService.storing(p)&&PowerAttributes.baseStrength(p,"a:steel")==partial,"Off stops further loss without restoring or duplicating the stored fraction");PowerData.state(p,"f:nicrosil",-1);s=open(p,ring);NicrosilService.store(s,0,"a:steel",.25);NicrosilService.request(p,new NicrosilNetwork.Request(NicrosilNetwork.STOP,s.token,NicrosilNetwork.ZERO,0,""));h.assertTrue(!NicrosilService.storing(p)&&PowerAttributes.baseStrength(p,"a:steel")==partial,"The Stop menu action cancels a target without moving any extra strength");NicrosilService.store(s,0,"a:steel",.25);p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);NicrosilService.storageTick(p,++storageClock);h.assertTrue(!NicrosilService.storing(p)&&PowerAttributes.baseStrength(p,"a:steel")==partial,"Losing contact stops a newly selected target before its next tick");p.setItemInHand(InteractionHand.OFF_HAND,ring);s=open(p,ring);NicrosilService.store(s,0,"a:steel",.25);Metalminds.wipe(ring);NicrosilService.storageTick(p,++storageClock);h.assertTrue(!NicrosilService.storing(p)&&NicrosilService.contents(p,ring)==null&&PowerAttributes.baseStrength(p,"a:steel")==partial,"A wiped destination cannot be silently recreated by a running plan");}finally{NicrosilConfig.POWER_RATE.set(rate);clean(p,ring);}h.succeed();
    }
    private static final class TestResource implements NicrosilResources.Provider {
        final Map<UUID,Double> balances=new HashMap<>();boolean enabled;double maximum=1000;boolean fail;
        public String label(){return "Test Investiture";}public double chargePerUnit(){return 2;}public double available(net.minecraft.server.level.ServerPlayer p){return enabled?balances.getOrDefault(p.getUUID(),0.0):0;}
        public boolean canReceive(net.minecraft.server.level.ServerPlayer p,double amount){return enabled&&balances.getOrDefault(p.getUUID(),0.0)+amount<=maximum;}
        public boolean extract(net.minecraft.server.level.ServerPlayer p,double amount){if(fail||available(p)<amount)return false;balances.put(p.getUUID(),available(p)-amount);return true;}
        public boolean insert(net.minecraft.server.level.ServerPlayer p,double amount){if(fail||!canReceive(p,amount))return false;balances.put(p.getUUID(),balances.getOrDefault(p.getUUID(),0.0)+amount);return true;}
    }
    @GameTest(template="empty") public static void resourceProviderTransfersConserveInvestitureAndKeepUnavailableEntries(GameTestHelper h){
        String key=CosmereArcanists.MOD_ID+":test_nicrosil_resource";var provider=(TestResource)NicrosilResources.get(key);if(provider==null){provider=new TestResource();NicrosilResources.register(ResourceLocation.parse(key),provider);}var donor=player(h,true);var ring=equip(donor);var receiver=player(h,false);try{provider.enabled=true;provider.fail=false;provider.maximum=1000;provider.balances.put(donor.getUUID(),400.0);unkey(donor);var s=open(donor,ring);provider.fail=true;store(s,1,key);h.assertTrue(provider.available(donor)==400&&NicrosilService.contents(donor,ring)==null,"Failed resource extraction changes neither side");provider.fail=false;store(s,1,key);var entry=NicrosilService.contents(donor,ring).entries().getFirst();h.assertTrue(entry.amount()==100&&provider.available(donor)==300&&Metalminds.charge(ring)==200,"Storage moves one bounded batch, charging the resource's own conversion rate");donor.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);receiver.setItemInHand(InteractionHand.OFF_HAND,ring);var tap=open(receiver,ring);provider.enabled=false;NicrosilService.tap(tap,entry.id());h.assertTrue(NicrosilService.contents(receiver,ring).entry(entry.id())!=null,"Disabling or removing a resource integration preserves stored Investiture");provider.enabled=true;provider.maximum=50;NicrosilService.tap(tap,entry.id());h.assertTrue(provider.available(receiver)==0&&Metalminds.charge(ring)==200,"Insufficient receiving capacity preserves the full stored batch");provider.maximum=1000;NicrosilService.tap(tap,entry.id());h.assertTrue(provider.available(receiver)==100&&provider.available(donor)==300&&!Metalminds.bound(ring),"Retrieval conserves resource quantity and empties the entry");}finally{provider.enabled=false;provider.fail=false;provider.maximum=1000;provider.balances.clear();clean(donor,ring);NicrosilService.clear(receiver);}h.succeed();
    }
    @GameTest(template="empty") public static void staleMenuTokensAndLostIdentityCannotAuthorizeAnotherTransfer(GameTestHelper h){
        var p=player(h,true);var ring=equip(p);try{PowerAttributes.set(p,"a:steel",1);PowerAttributes.set(p,"a:iron",1);var s=open(p,ring);UUID original=s.token;store(s,0,"a:steel");h.assertTrue(!original.equals(s.token),"Successful transfers rotate the menu token");NicrosilService.request(p,new NicrosilNetwork.Request(NicrosilNetwork.STORE,original,NicrosilNetwork.ZERO,0,"a:iron"));h.assertTrue(PowerAttributes.baseStrength(p,"a:iron")==1&&NicrosilService.contents(p,ring).entries().size()==1,"An old menu request cannot remove a different power");NicrosilService.clear(p);h.assertTrue(NicrosilService.session(p)==null,"Closing removes server menu authority");}finally{clean(p,ring);}h.succeed();
    }
}
